185	                <Text color={theme.ui.comment}>| </Text>
186	                <ConsoleSummaryDisplay errorCount={errorCount} />
187	              </Box>
188	            )}
189	          </Box>
190	        </Box>
191	      )}
192	    </Box>
193	  );
194	};
