32	  const [timerResetKey, setTimerResetKey] = useState(0);
33	  const isTimerActive = streamingState === StreamingState.Responding;
34	
35	  const elapsedTimeFromTimer = useTimer(isTimerActive, timerResetKey);
36	
37	  const isPhraseCyclingActive = streamingState === StreamingState.Responding;
38	  const isWaiting = streamingState === StreamingState.WaitingForConfirmation;
39	  const currentLoadingPhrase = usePhraseCycler(
40	    isPhraseCyclingActive,
41	    isWaiting,
42	    shouldShowFocusHint,
43	    loadingPhrasesMode,
44	    customWittyPhrases,
45	  );
